<div class="page-heading"><div><span class="eyebrow">Hospital · Appointment outcomes</span><h1>Appointments</h1><p>Update approved appointments to Vaccinated or Not vaccinated.</p></div></div>
<nav class="filter-tabs" aria-label="Appointment status"><?php foreach (['approved' => 'Approved', 'completed' => 'Vaccinated', 'not_vaccinated' => 'Not vaccinated', 'all' => 'All'] as $key => $label): ?><a href="<?= e(url('hospital.appointments', ['status' => $key])) ?>" <?= $status === $key ? 'aria-current="page"' : '' ?>><?= e($label) ?></a><?php endforeach; ?></nav>
<section class="request-grid hospital-request-grid"><?php foreach ($appointments as $appointment): ?><article class="request-card"><div class="request-top"><span class="status status-<?= e($appointment['status']) ?>"><?= e($appointment['status'] === 'completed' ? 'Vaccinated' : status_label($appointment['status'])) ?></span><time><?= e(display_date($appointment['appointment_date'])) ?> · <?= e(display_date($appointment['appointment_time'], 'g:i A')) ?></time></div><h2><?= e($appointment['child_name']) ?></h2><p class="request-vaccine"><?= e($appointment['vaccine_name']) ?> · <?= e($appointment['dose_label']) ?></p><dl><div><dt>Child profile</dt><dd><?= e(age_label($appointment['date_of_birth'])) ?> · <?= e(status_label($appointment['gender'])) ?><?= $appointment['blood_group'] ? ' · ' . e($appointment['blood_group']) : '' ?></dd></div><div><dt>Parent</dt><dd><?= e($appointment['parent_name']) ?><small><?= e($appointment['parent_phone'] ?: 'No phone') ?></small></dd></div><div><dt>Medical notes</dt><dd><?= e($appointment['medical_notes'] ?: 'No medical notes') ?></dd></div></dl><?php if ($appointment['status'] === 'approved'): ?><form method="post" action="<?= e(url('hospital.appointment.update')) ?>" data-outcome-form><?= csrf_field() ?><input type="hidden" name="appointment_id" value="<?= (int) $appointment['id'] ?>"><div class="segmented"><label><input type="radio" name="outcome" value="completed" required><span>Vaccinated</span></label><label><input type="radio" name="outcome" value="not_vaccinated" required><span>Not vaccinated</span></label></div><label data-batch-field>Batch number<input name="batch_number" maxlength="80" placeholder="Required when vaccinated"></label><label>Hospital note <small>Optional for vaccinated; recommended otherwise</small><textarea name="hospital_notes" maxlength="500" rows="2"></textarea></label><button class="button button-full" type="submit">Save outcome</button></form><?php else: ?><div class="note"><strong><?= $appointment['status'] === 'completed' ? 'Vaccination record' : 'Outcome note' ?></strong><p><?php if ($appointment['status'] === 'completed'): ?>Batch <?= e($appointment['batch_number'] ?: 'not recorded') ?> · <?= e(display_date($appointment['administered_at'], 'd M Y, g:i A')) ?><?php else: ?><?= e($appointment['hospital_notes'] ?: 'No note recorded') ?><?php endif; ?></p></div><?php endif; ?></article><?php endforeach; ?><?php if (!$appointments): ?><div class="empty-state compact"><span class="empty-icon">✓</span><h2>No <?= e(status_label($status)) ?> appointments</h2><p>There is nothing in this view.</p></div><?php endif; ?></section>
